import assert from "node:assert"

function _min(heights: number[], left: number, right: number): number {
  let minIndices = [left]

  for (let i = left + 1; i <= right; i++) {
    if (heights[i] < heights[minIndices[0]]) {
      minIndices = [i]
    } else if (heights[i] == heights[minIndices[0]]) {
      minIndices.push(i)
    }
  }

  return minIndices[Math.floor(minIndices.length/2)]
}

function _largestRectangle(
  heights: number[],
  left: number,
  right: number,
): number {
  if (left > right) return 0

  const minIndex = _min(heights, left, right)

  // console.log({left, right, minIndex})

  return Math.max(
    heights[minIndex] * (right - left + 1),
    _largestRectangle(heights, left, minIndex - 1),
    _largestRectangle(heights, minIndex + 1, right),
  )
}

function largestRectangleArea(heights: number[]): number {
  return _largestRectangle(heights, 0, heights.length - 1)
}

assert.equal(largestRectangleArea([2, 1, 5, 6, 2, 3]), 10)
assert.equal(largestRectangleArea([2, 4]), 4)
